  'ta.level': ['{c}: level it up from {now} to {target}', '{c}: súbelo del nivel {now} al {target}', '{c}: suba do nível {now} ao {target}', '{c} : montez-le du niveau {now} au {target}', '{c}: von Level {now} auf {target} bringen', '{c}：Lv{now}→{target}に上げる', '{c}: 레벨 {now} → {target}', '{c}：从 {now} 级升到 {target} 级'],
  'ta.skills': ['{c}: raise skills to level 10 (now {low})', '{c}: sube sus habilidades a nivel 10 (ahora {low})', '{c}: suba as habilidades ao nível 10 (agora {low})', '{c} : compétences au niveau 10 (actuellement {low})', '{c}: Skills auf Stufe 10 (jetzt {low})', '{c}：スキルをLv10に（現在 {low}）', '{c}: 스킬 10레벨로 (현재 {low})', '{c}：技能升到 10 级（当前 {low}）'],
  'ta.sp': ['{c}: unlock their SP awakening', '{c}: desbloquea su despertar SP', '{c}: desbloqueie o despertar SP', '{c} : débloquez son éveil SP', '{c}: SP-Erweckung freischalten', '{c}：SP覚醒を解放', '{c}: SP 각성 해방', '{c}：解锁 SP 觉醒'],
  'ta.dupes': ['{c}: with {min} dupes it becomes rank {rank} (you have {now})', '{c}: con {min} dupes pasa a rango {rank} (tienes {now})', '{c}: com {min} dupes vira rank {rank} (você tem {now})', '{c} : avec {min} doublons, rang {rank} (vous en avez {now})', '{c}: mit {min} Dupes Rang {rank} (du hast {now})', '{c}：{min}凸で{rank}ランク（現在{now}凸）', '{c}: {min}돌파 시 {rank} 등급 (현재 {now})', '{c}：{min} 突破可达 {rank} 级（当前 {now}）'],
