export type GameKey = keyof typeof T;

export function useG(lang: Locale) {
  const idx = Math.max(0, ORDER.indexOf(lang));
  return (key: GameKey, vars?: Record<string, string | number>) => {
    let s: string = T[key]?.[idx] ?? T[key]?.[0] ?? key;
    if (vars) for (const [k, v] of Object.entries(vars)) s = s.replace(`{${k}}`, String(v));
    return s;
  };
}

/** Diccionario plano de las claves pedidas, para pasarlo a componentes React. */
export function gameDict<K extends GameKey>(lang: Locale, keys: readonly K[]): Record<K, string> {
  const g = useG(lang);
  return Object.fromEntries(keys.map((k) => [k, g(k)])) as Record<K, string>;
}
